impl IErc165 for Ownable {
    fn supports_interface(&self, interface_id: B32) -> bool {
        <Self as IOwnable>::interface_id() == interface_id
            || <Self as IErc165>::interface_id() == interface_id
    }
}

use stylus_sdk::prelude::errors::MethodError;
#[cfg(test)]
mod tests {
    use crate::test_support::{test_address, TestContract as TestVMContract};
    use stylus_sdk::{alloy_primitives::Address, prelude::*};

    use super::*;
    use crate::utils::introspection::erc165::IErc165;

    unsafe impl TopLevelStorage for Ownable {}

    #[test]
    fn constructor() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        contract.sender(alice).constructor(alice).unwrap();

        let owner = contract.sender(alice).owner();
        assert_eq!(owner, alice);

        contract.assert_emitted(&OwnershipTransferred {
            previous_owner: Address::ZERO,
            new_owner: alice,
        });
    }

    #[test]
    fn constructor_reverts_when_invalid_owner() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        let err = contract
            .sender(alice)
            .constructor(Address::ZERO)
            .expect_err("should revert");
        assert!(
            matches!(err, Error::InvalidOwner(OwnableInvalidOwner { owner }) if owner == Address::ZERO)
        );
    }

    #[test]
    fn transfers_ownership() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        contract.sender(alice).constructor(alice).unwrap();

        contract
            .sender(alice)
            .transfer_ownership(bob)
            .expect("should transfer ownership");
        let owner = contract.sender(alice).owner();
        assert_eq!(owner, bob);

        contract.assert_emitted(&OwnershipTransferred {
            previous_owner: alice,
            new_owner: bob,
        });
    }

    #[test]
    fn prevents_non_owners_from_transferring() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        contract.sender(alice).constructor(bob).unwrap();

        let err = contract.sender(alice).transfer_ownership(bob).unwrap_err();
        assert!(matches!(err, Error::UnauthorizedAccount(_)));
    }

    #[test]
    fn prevents_reaching_stuck_state() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        contract.sender(alice).constructor(alice).unwrap();

        let err = contract
            .sender(alice)
            .transfer_ownership(Address::ZERO)
            .unwrap_err();

        assert!(matches!(err, Error::InvalidOwner(_)));
    }

    #[test]
    fn loses_ownership_after_renouncing() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        contract.sender(alice).constructor(alice).unwrap();

        contract
            .sender(alice)
            .renounce_ownership()
            .expect("should renounce ownership");
        let owner = contract.sender(alice).owner();
        assert_eq!(owner, Address::ZERO);

        contract.assert_emitted(&OwnershipTransferred {
            previous_owner: alice,
            new_owner: Address::ZERO,
        });
    }

    #[test]
    fn prevents_non_owners_from_renouncing() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        contract.sender(alice).constructor(bob).unwrap();

        let err = contract.sender(alice).renounce_ownership().unwrap_err();
        assert!(matches!(err, Error::UnauthorizedAccount(_)));
    }

    #[test]
    fn recovers_access_using_internal_transfer() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));
        let bob = test_address(stringify!(bob));

        contract.sender(alice).constructor(bob).unwrap();

        contract.sender(alice)._transfer_ownership(bob);
        let owner = contract.sender(alice).owner();
        assert_eq!(owner, bob);
    }

    #[test]
    fn interface_id() {
        let actual = <Ownable as IOwnable>::interface_id();
        let expected: B32 = 0xe083076_u32.into();
        assert_eq!(actual, expected);
    }

    #[test]
    fn supports_interface() {
        let contract = TestVMContract::<Ownable>::new(stringify!(contract));
        let alice = test_address(stringify!(alice));

        assert!(contract
            .sender(alice)
            .supports_interface(<Ownable as IOwnable>::interface_id()));
        assert!(contract
            .sender(alice)
            .supports_interface(<Ownable as IErc165>::interface_id()));

        let fake_interface_id: B32 = 0x12345678_u32.into();
        assert!(!contract.sender(alice).supports_interface(fake_interface_id));
    }
}

impl IAccessControl for AccessControl {
    type Error = Error;

    fn has_role(&self, role: B256, account: Address) -> bool {
        self.roles.getter(role).has_role.get(account)
    }

    fn only_role(&self, role: B256) -> Result<(), Error> {
        self._check_role(role, self.vm().msg_sender())
    }

    fn get_role_admin(&self, role: B256) -> B256 {
        self.roles.getter(role).admin_role.get()
    }

    fn grant_role(
        &mut self,
        role: B256,
        account: Address,
    ) -> Result<(), Error> {
        let admin_role = self.get_role_admin(role);
        self.only_role(admin_role)?;
        self._grant_role(role, account);
        Ok(())
    }

    fn revoke_role(
        &mut self,
        role: B256,
        account: Address,
    ) -> Result<(), Error> {
        let admin_role = self.get_role_admin(role);
        self.only_role(admin_role)?;
        self._revoke_role(role, account);
        Ok(())
    }

    fn renounce_role(
        &mut self,
        role: B256,
        confirmation: Address,
    ) -> Result<(), Error> {
        if self.vm().msg_sender() != confirmation {
            return Err(Error::BadConfirmation(
                AccessControlBadConfirmation {},
            ));
        }

        self._revoke_role(role, confirmation);
        Ok(())
    }
}

impl AccessControl {
    /// The default admin role. `[0; 32]` by default.
    pub const DEFAULT_ADMIN_ROLE: [u8; 32] = [0; 32];

    /// Sets `admin_role` as `role`'s admin role.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `role` - The identifier of the role we are changing the admin to.
    /// * `new_admin_role` - The new admin role.
    ///
    /// # Events
    ///
    /// * [`RoleAdminChanged`].
    pub fn _set_role_admin(&mut self, role: B256, new_admin_role: B256) {
        let previous_admin_role = self.get_role_admin(role);
        self.roles.setter(role).admin_role.set(new_admin_role);
        self.vm().log(RoleAdminChanged {
            role,
            previous_admin_role,
            new_admin_role,
        });
    }

    /// Checks if `account` has been granted `role`.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `role` - The role identifier.
    /// * `account` - The account to check for membership.
    ///
    /// # Errors
    ///
    /// * [`Error::UnauthorizedAccount`] - If the caller has not been
    ///   granted `role`.
    pub fn _check_role(
        &self,
        role: B256,
        account: Address,
    ) -> Result<(), Error> {
        if !self.has_role(role, account) {
            return Err(Error::UnauthorizedAccount(
                AccessControlUnauthorizedAccount { account, needed_role: role },
            ));
        }

        Ok(())
    }

    /// Attempts to grant `role` to `account` and returns a boolean indicating
    /// if `role` was granted.
    ///
    /// Internal function without access restriction.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `role` - The role identifier.
    /// * `account` - The account which will be granted the role.
    ///
    /// # Events
    ///
    /// * [`RoleGranted`].
    pub fn _grant_role(&mut self, role: B256, account: Address) -> bool {
        if self.has_role(role, account) {
            false
        } else {
            self.roles.setter(role).has_role.insert(account, true);
            self.vm().log(RoleGranted {
                role,
                account,
                sender: self.vm().msg_sender(),
            });
            true
        }
    }

    /// Attempts to revoke `role` from `account` and returns a boolean
    /// indicating if `role` was revoked.
    ///
    /// Internal function without access restriction.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `role` - The role identifier.
    /// * `account` - The account which will be granted the role.
    ///
    /// # Events
    ///
    /// * [`RoleRevoked`].
    pub fn _revoke_role(&mut self, role: B256, account: Address) -> bool {
        if self.has_role(role, account) {
            self.roles.setter(role).has_role.insert(account, false);
            self.vm().log(RoleRevoked {
                role,
                account,
                sender: self.vm().msg_sender(),
            });
            true
        } else {
            false
        }
    }
}

