#[public]
#[implements(IErc721<Error = Error>, IErc165)]
impl Erc721 {}

#[public]
impl IErc721 for Erc721 {
    type Error = Error;

    fn balance_of(&self, owner: Address) -> Result<U256, Error> {
        if owner.is_zero() {
            return Err(ERC721InvalidOwner { owner: Address::ZERO }.into());
        }
        Ok(self.balances.get(owner))
    }

    fn owner_of(&self, token_id: U256) -> Result<Address, Error> {
        self._require_owned(token_id)
    }

    fn safe_transfer_from(
        &mut self,
        from: Address,
        to: Address,
        token_id: U256,
    ) -> Result<(), Error> {
        self.safe_transfer_from_with_data(from, to, token_id, vec![].into())
    }

    #[selector(name = "safeTransferFrom")]
    fn safe_transfer_from_with_data(
        &mut self,
        from: Address,
        to: Address,
        token_id: U256,
        data: Bytes,
    ) -> Result<(), Error> {
        self.transfer_from(from, to, token_id)?;
        self._check_on_erc721_received(
            self.vm().msg_sender(),
            from,
            to,
            token_id,
            &data,
        )
    }

    fn transfer_from(
        &mut self,
        from: Address,
        to: Address,
        token_id: U256,
    ) -> Result<(), Error> {
        if to.is_zero() {
            return Err(
                ERC721InvalidReceiver { receiver: Address::ZERO }.into()
            );
        }

        let owner = self._owner_of(token_id);
        self._check_authorized(owner, self.vm().msg_sender(), token_id)?;
        if owner != from {
            return Err(ERC721IncorrectOwner {
                sender: from,
                token_id,
                owner,
            }
            .into());
        }

        self._update(to, token_id, Address::ZERO)?;
        Ok(())
    }

    fn approve(&mut self, to: Address, token_id: U256) -> Result<(), Error> {
        self._approve(to, token_id, self.vm().msg_sender(), true)
    }

    fn set_approval_for_all(
        &mut self,
        operator: Address,
        approved: bool,
    ) -> Result<(), Error> {
        self._set_approval_for_all(self.vm().msg_sender(), operator, approved)
    }

    fn get_approved(&self, token_id: U256) -> Result<Address, Error> {
        self._require_owned(token_id)?;
        Ok(self._get_approved(token_id))
    }

    fn is_approved_for_all(&self, owner: Address, operator: Address) -> bool {
        self.operator_approvals.get(owner).get(operator)
    }
}

#[public]
impl IErc165 for Erc721 {
    fn supports_interface(&self, interface_id: B32) -> bool {
        <Self as IErc721>::interface_id() == interface_id
            || <Self as IErc165>::interface_id() == interface_id
    }
}

impl Erc721 {
    /// Returns the owner of the `token_id`. Does NOT revert if the token
    /// doesn't exist.
    ///
    /// IMPORTANT: Any overrides to this function that add ownership of tokens
    /// not tracked by the core [`Erc721`] logic MUST be matched with the use
    /// of [`Self::_increase_balance`] to keep balances consistent with
    /// ownership. The invariant to preserve is that for any address `a` the
    /// value returned by [`Self::balance_of(a)`][Self::balance_of] must be
    /// equal to the number of tokens such that
    /// [`Self::_owner_of(token_id)`][Self::_owner_of] is `a`.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `token_id` - Token id as a number.
    #[must_use]
    pub fn _owner_of(&self, token_id: U256) -> Address {
        self.owners.get(token_id)
    }

    /// Returns the approved address for `token_id`.
    /// Returns 0 if `token_id` is not minted.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `token_id` - Token id as a number.
    #[must_use]
    pub fn _get_approved(&self, token_id: U256) -> Address {
        self.token_approvals.get(token_id)
    }

    /// Returns whether `spender` is allowed to manage `owner`'s tokens, or
    /// `token_id` in particular (ignoring whether it is owned by `owner`).
    ///
    /// WARNING: This function assumes that `owner` is the actual owner of
    /// `token_id` and does not verify this assumption.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `owner` - Account of the token's owner.
    /// * `spender` - Account that will spend token.
    /// * `token_id` - Token id as a number.
    #[must_use]
    pub fn _is_authorized(
        &self,
        owner: Address,
        spender: Address,
        token_id: U256,
    ) -> bool {
        !spender.is_zero()
            && (owner == spender
                || self.is_approved_for_all(owner, spender)
                || self._get_approved(token_id) == spender)
    }

    /// Checks if `operator` can operate on `token_id`, assuming the provided
    /// `owner` is the actual owner. Reverts if:
    /// - `operator` does not have approval from `owner` for `token_id`.
    /// - `operator` does not have approval to manage all of `owner`'s assets.
    ///
    /// WARNING: This function assumes that `owner` is the actual owner of
    /// `token_id` and does not verify this assumption.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `owner` - Account of the token's owner.
    /// * `operator` - Account that will spend token.
    /// * `token_id` - Token id as a number.
    ///
    /// # Errors
    ///
    /// * [`Error::NonexistentToken`] - If the token does not exist.
    /// * [`Error::InsufficientApproval`] - If `spender` does not have the right
    ///   to approve.
    pub fn _check_authorized(
        &self,
        owner: Address,
        operator: Address,
        token_id: U256,
    ) -> Result<(), Error> {
        if self._is_authorized(owner, operator, token_id) {
            return Ok(());
        }

        if owner.is_zero() {
            Err(ERC721NonexistentToken { token_id }.into())
        } else {
            Err(ERC721InsufficientApproval { operator, token_id }.into())
        }
    }

    /// Unsafe write access to the balances, used by extensions that "mint"
    /// tokens using an [`Self::owner_of`] override.
    ///
    /// NOTE: the value is limited to type(uint128).max. This protects against
    /// _balance overflow. It is unrealistic that a `U256` would ever
    /// overflow from increments when these increments are bounded to `u128`
    /// values.
    ///
    /// WARNING: Increasing an account's balance using this function tends to
    /// be paired with an override of the [`Self::_owner_of`] function to
    /// resolve the ownership of the corresponding tokens so that balances and
    /// ownership remain consistent with one another.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `account` - Account to increase balance.
    /// * `value` - The number of tokens to increase balance.
    pub fn _increase_balance(&mut self, account: Address, value: U128) {
        self.balances.setter(account).add_assign_unchecked(U256::from(value));
    }

    /// Transfers `token_id` from its current owner to `to`, or alternatively
    /// mints (or burns) if the current owner (or `to`) is the
    /// [`Address::ZERO`]. Returns the owner of the `token_id` before the
    /// update.
    ///
    /// The `auth` argument is optional. If the value passed is non-zero, then
    /// this function will check that `auth` is either the owner of the
    /// token, or approved to operate on the token (by the owner).
    ///
    /// NOTE: If overriding this function in a way that tracks balances, see
    /// also [`Self::_increase_balance`].
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Account of the recipient.
    /// * `token_id` - Token id as a number.
    /// * `auth` - Account used for authorization of the update.
    ///
    /// # Errors
    ///
    /// * [`Error::NonexistentToken`] - If the token does not exist and `auth`
    ///   is not [`Address::ZERO`].
    /// * [`Error::InsufficientApproval`] - If `auth` is not [`Address::ZERO`]
    ///   and `auth` does not have a right to approve this token.
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    pub fn _update(
        &mut self,
        to: Address,
        token_id: U256,
        auth: Address,
    ) -> Result<Address, Error> {
        let from = self._owner_of(token_id);

        // Perform (optional) operator check.
        if !auth.is_zero() {
            self._check_authorized(from, auth, token_id)?;
        }

        // Execute the update.
        if !from.is_zero() {
            // Clear approval. No need to re-authorize or emit the `Approval`
            // event.
            self._approve(Address::ZERO, token_id, Address::ZERO, false)?;
            self.balances.setter(from).sub_assign_unchecked(uint!(1_U256));
        }

        if !to.is_zero() {
            self.balances.setter(to).add_assign_unchecked(uint!(1_U256));
        }

        self.owners.setter(token_id).set(to);
        self.vm().log(Transfer { from, to, token_id });
        Ok(from)
    }

    /// Mints `token_id` and transfers it to `to`.
    ///
    /// WARNING: Usage of this method is discouraged, use [`Self::_safe_mint`]
    /// whenever possible.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Account of the recipient.
    /// * `token_id` - Token id as a number.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSender`] - If `token_id` already exists.
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    pub fn _mint(&mut self, to: Address, token_id: U256) -> Result<(), Error> {
        if to.is_zero() {
            return Err(
                ERC721InvalidReceiver { receiver: Address::ZERO }.into()
            );
        }

        if !self._owner_of(token_id).is_zero() {
            return Err(ERC721InvalidSender { sender: Address::ZERO }.into());
        }

        self._update(to, token_id, Address::ZERO)?;
        Ok(())
    }

    /// Mints `token_id`, transfers it to `to`,
    /// and checks for `to`'s acceptance.
    ///
    /// An additional `data` parameter is forwarded to
    /// [`IErc721Receiver::on_erc721_received`] to contract recipients.
    ///
    /// The ownership update happens before the receiver callback. If this
    /// method returns a receiver error, callers must propagate it so the EVM
    /// reverts the update; swallowing it leaves the mint applied.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Account of the recipient.
    /// * `token_id` - Token id as a number.
    /// * `data` - Additional data with no specified format, sent in the call to
    ///   [`Erc721::_check_on_erc721_received`].
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSender`] - If `token_id` already exists.
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    /// * [`Error::InvalidReceiver`] - If
    ///   [`IErc721Receiver::on_erc721_received`] hasn't returned its interface
    ///   id or returned with an error.
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    pub fn _safe_mint(
        &mut self,
        to: Address,
        token_id: U256,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._mint(to, token_id)?;
        self._check_on_erc721_received(
            self.vm().msg_sender(),
            Address::ZERO,
            to,
            token_id,
            data,
        )
    }

    /// Destroys `token_id`.
    ///
    /// The approval is cleared when the token is burned. This is an
    /// internal function that does not check if the sender is authorized
    /// to operate on the token.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` - Token id as a number.
    ///
    /// # Errors
    ///
    /// * [`Error::NonexistentToken`] - If the token does not exist.
    ///
    /// # Events
    ///
    /// * [`Transfer`].
    pub fn _burn(&mut self, token_id: U256) -> Result<(), Error> {
        if self._owner_of(token_id).is_zero() {
            return Err(ERC721NonexistentToken { token_id }.into());
        }

        self._update(Address::ZERO, token_id, Address::ZERO)?;
        Ok(())
    }

    /// Transfers `token_id` from `from` to `to`.
    ///
    /// As opposed to [`Self::transfer_from`], this imposes no restrictions on
    /// the caller.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account of the sender.
    /// * `to` - Account of the recipient.
    /// * `token_id` - Token id as a number.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    /// * [`Error::NonexistentToken`] - If `token_id` does not exist.
    /// * [`Error::IncorrectOwner`] - If the previous owner is not `from`.
    ///

        value: U256,
        data: Bytes,
    ) -> Result<(), Self::Error>;

    /// Batched version of [`IErc1155::safe_transfer_from`].
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to transfer tokens from.
    /// * `to` - Account of the recipient.
    /// * `ids` - Array of all tokens ids.
    /// * `values` - Array of all amount of tokens to be transferred.
    /// * `data` - Additional data with no specified format, sent in call to
    ///   `to`.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] - Returned when `to` is [`Address::ZERO`]
    ///   or when [`IErc1155Receiver::on_erc1155_batch_received`] hasn't
    ///   returned its interface id or returned with error.
    /// * [`Error::InvalidSender`] - Returned when `from` is [`Address::ZERO`].
    /// * [`Error::InvalidArrayLength`] - Returned when the length of `ids` is
    ///   not equal to the length of `values`.
    /// * [`Error::InsufficientBalance`] - Returned when any of the `values` is
    ///   greater than the balance of the `from` account.
    /// * [`Error::MissingApprovalForAll`] - Returned when `from` is not the
    ///   caller (the caller), and the caller does not have the right to
    ///   approve.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`] - If the arrays contain one element.
    /// * [`TransferBatch`] - If the arrays contain multiple elements.
    fn safe_batch_transfer_from(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: Bytes,
    ) -> Result<(), Self::Error>;
}

#[public]
#[implements(IErc1155<Error = Error>, IErc165)]
impl Erc1155 {}

#[public]
impl IErc1155 for Erc1155 {
    type Error = Error;

    fn balance_of(&self, account: Address, id: U256) -> U256 {
        self.balances.get(id).get(account)
    }

    fn balance_of_batch(
        &self,
        accounts: Vec<Address>,
        ids: Vec<U256>,
    ) -> Result<Vec<U256>, Error> {
        Self::require_equal_arrays_length(&ids, &accounts)?;

        let balances: Vec<U256> = accounts
            .iter()
            .zip(ids.iter())
            .map(|(account, token_id)| self.balance_of(*account, *token_id))
            .collect();

        Ok(balances)
    }

    fn set_approval_for_all(
        &mut self,
        operator: Address,
        approved: bool,
    ) -> Result<(), Error> {
        self._set_approval_for_all(self.vm().msg_sender(), operator, approved)
    }

    fn is_approved_for_all(&self, account: Address, operator: Address) -> bool {
        self.operator_approvals.get(account).get(operator)
    }

    fn safe_transfer_from(
        &mut self,
        from: Address,
        to: Address,
        id: U256,
        value: U256,
        data: Bytes,
    ) -> Result<(), Error> {
        self.authorize_transfer(from)?;
        self.do_safe_transfer_from(from, to, vec![id], vec![value], &data)
    }

    fn safe_batch_transfer_from(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: Bytes,
    ) -> Result<(), Error> {
        self.authorize_transfer(from)?;
        self.do_safe_transfer_from(from, to, ids, values, &data)
    }
}

#[public]
impl IErc165 for Erc1155 {
    fn supports_interface(&self, interface_id: B32) -> bool {
        <Self as IErc1155>::interface_id() == interface_id
            || <Self as IErc165>::interface_id() == interface_id
    }
}

impl Erc1155 {
    /// Transfers a `value` amount of tokens of type `ids` from `from` to
    /// `to`. Will mint (or burn) if `from` (or `to`) is the [`Address::ZERO`].
    ///
    /// NOTE: The ERC-1155 acceptance check is not performed in this function.
    /// See [`Self::_update_with_acceptance_check`] instead.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to transfer tokens from.
    /// * `to` - Account of the recipient.
    /// * `ids` - Array of all tokens ids.
    /// * `values` - Array of all amount of tokens to be transferred.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidArrayLength`] - If length of `ids` is not equal to
    ///   length of `values`.
    /// * [`Error::InsufficientBalance`] - If `value` is greater than the
    ///   balance of the `from` account.
    ///
    ///
    /// # Events
    ///
    /// * [`TransferSingle`] - If the arrays contain one element.
    /// * [`TransferBatch`] - If the arrays contain multiple elements.
    ///
    /// # Panics
    ///
    /// * If updated balance exceeds [`U256::MAX`], may happen during `mint`
    ///   operation.
    fn _update(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), Error> {
        Self::require_equal_arrays_length(&ids, &values)?;

        // Preflight source balances so a later insufficient item cannot leave
        // earlier batch items applied when a caller catches the returned Err.
        // A self-transfer subtracts and adds each item immediately, so each
        // item is checked against the unchanged balance independently.
        if !from.is_zero() && from != to {
            let mut remaining_balances: Vec<(U256, U256)> = Vec::new();
            for (&token_id, &value) in ids.iter().zip(values.iter()) {
                let index = remaining_balances
                    .iter()
                    .position(|(id, _)| *id == token_id);
                let balance = match index {
                    Some(index) => remaining_balances[index].1,
                    None => self.balance_of(from, token_id),
                };

                if balance < value {
                    return Err(Error::InsufficientBalance(
                        ERC1155InsufficientBalance {
                            sender: from,
                            balance,
                            needed: value,
                            token_id,
                        },
                    ));
                }

                let remaining = balance - value;
                if let Some(index) = index {
                    remaining_balances[index].1 = remaining;
                } else {
                    remaining_balances.push((token_id, remaining));
                }
            }
        }

        let operator = self.vm().msg_sender();

        for (&token_id, &value) in ids.iter().zip(values.iter()) {
            self.do_update(from, to, token_id, value)?;
        }

        if ids.len() == 1 {
            let id = ids[0];
            let value = values[0];
            self.vm().log(TransferSingle { operator, from, to, id, value });
        } else {
            self.vm().log(TransferBatch { operator, from, to, ids, values });
        }

        Ok(())
    }

    /// Version of [`Self::_update`] that performs the token acceptance check by
    /// calling [`IErc1155Receiver::on_erc1155_received`] or
    /// [`IErc1155Receiver::on_erc1155_batch_received`] on the receiver address
    /// if it contains code.
    ///
    /// Storage is updated before the receiver callback. If the callback
    /// returns an error, propagate it from the public entry point so the EVM
    /// reverts the update; swallowing it leaves the token update applied.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to transfer tokens from.
    /// * `to` - Account of the recipient.
    /// * `ids` - Array of all token ids.
    /// * `values` - Array of all amount of tokens to be transferred.
    /// * `data` - Additional data with no specified format, sent in call to
    ///   `to`.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidArrayLength`] - Returned when length of `ids` is not
    ///   equal to length of `values`.
    /// * [`Error::InsufficientBalance`] - Returned when `value` is greater than
    ///   the balance of the `from` account.
    /// * [`Error::InvalidReceiver`] - Returned when
    ///   [`IErc1155Receiver::on_erc1155_received`] or
    ///   [`IErc1155Receiver::on_erc1155_batch_received`] hasn't returned its
    ///   interface id or returned with error.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`] - If the arrays contain one element.
    /// * [`TransferBatch`] - If the arrays contain multiple elements.
    ///
    /// # Panics
    ///
    /// * If updated balance exceeds [`U256::MAX`], may happen during `mint`
    ///   operation.
    fn _update_with_acceptance_check(
        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._update(from, to, ids.clone(), values.clone())?;

        if !to.is_zero() {
            self._check_on_erc1155_received(
                self.vm().msg_sender(),
                from,
                to,
                Erc1155ReceiverData::new(ids, values),
                data.to_vec().into(),
            )?;
        }

        Ok(())
    }

    /// Creates a `value` amount of tokens of type `id`, and assigns
    /// them to `to`.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Account of the recipient.
    /// * `id` - Token id.
    /// * `value` - Amount of tokens to be minted.
    /// * `data` - Additional data with no specified format, sent in call to
    ///   `to`.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] - If `to` is [`Address::ZERO`].
    /// * [`Error::InvalidReceiver`] - If
    ///   [`IErc1155Receiver::on_erc1155_received`] hasn't returned its
    ///   interface id or returned with error.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`].
    ///
    /// # Panics
    ///
    /// * If updated balance exceeds [`U256::MAX`].
    pub fn _mint(
        &mut self,
        to: Address,
        id: U256,
        value: U256,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._do_mint(to, vec![id], vec![value], data)
    }

    /// Batched version of [`Self::_mint`].
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Account of the recipient.
    /// * `ids` - Array of all tokens ids to be minted.
    /// * `values` - Array of all amounts of tokens to be minted.
    /// * `data` - Additional data with no specified format, sent in call to
    ///   `to`.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidReceiver`] -  If `to` is [`Address::ZERO`].
    /// * [`Error::InvalidArrayLength`] - If length of `ids` is not equal to
    ///   length of `values`.
    /// * [`IErc1155Receiver::on_erc1155_received`] - If  hasn't returned its
    /// * [`Error::InvalidReceiver`] - interface id or returned with error.
    /// * [`Error::InvalidReceiver`] - If
    ///   [`IErc1155Receiver::on_erc1155_batch_received`] hasn't returned its
    ///   interface id or returned with error.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`] - If the arrays contain one element.
    /// * [`TransferBatch`] - If the arrays contain multiple elements.
    ///
    /// # Panics
    ///
    /// * If updated balance exceeds [`U256::MAX`].
    pub fn _mint_batch(
        &mut self,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._do_mint(to, ids, values, data)
    }

    /// Destroys a `value` amount of tokens of type `id` from `from`.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to burn tokens from.
    /// * `id` - Token id to be burnt.
    /// * `value` - Amount of tokens to be burnt.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSender`] - If `from` is the [`Address::ZERO`].
    /// * [`Error::InsufficientBalance`]  - If `value` is greater than the
    ///   balance of the `from` account.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`].
    pub fn _burn(
        &mut self,
        from: Address,
        id: U256,
        value: U256,
    ) -> Result<(), Error> {
        self._do_burn(from, vec![id], vec![value])
    }

    /// Batched version of [`Self::_burn`].
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account to burn tokens from.
    /// * `ids` - Array of all tokens ids to be burnt.
    /// * `values` - Array of all amounts of tokens to be burnt.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidSender`] - If `from` is the [`Address::ZERO`].
    /// * [`Error::InvalidArrayLength`] - If length of `ids` is not equal to
    ///   length of `values`.
    /// * [`Error::InsufficientBalance`] - If any of the `values` is greater
    ///   than the balance of the respective token from `tokens` of the `from`
    ///   account.
    ///
    /// # Events
    ///
    /// * [`TransferSingle`] - If the arrays contain one element.
    /// * [`TransferBatch`] - If the arrays contain multiple elements.
    pub fn _burn_batch(
        &mut self,
        from: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), Error> {
        self._do_burn(from, ids, values)
    }

    /// Approve `operator` to operate on all of `owner` tokens.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `owner` - Tokens owner (the caller).
    /// * `operator` - Account to add to the set of authorized operators.
    /// * `approved` - Flag that determines whether or not permission will be
    ///   granted to `operator`. If true, this means `operator` will be allowed
    ///   to manage `owner`'s assets.
    ///
    /// # Errors
    ///
    /// * [`Error::InvalidOperator`] - If `operator` is the [`Address::ZERO`].
    ///
    /// # Events
    ///
    /// * [`ApprovalForAll`].
    fn _set_approval_for_all(
        &mut self,
        owner: Address,
        operator: Address,
        approved: bool,
    ) -> Result<(), Error> {
        if operator.is_zero() {
            return Err(Error::InvalidOperator(ERC1155InvalidOperator {
                operator,
            }));
        }
        self.operator_approvals.setter(owner).setter(operator).set(approved);
        self.vm().log(ApprovalForAll { account: owner, operator, approved });
        Ok(())
    }
}

impl Erc1155 {
    /// Performs an acceptance check for the provided `operator` by calling
    /// [`IErc1155Receiver::on_erc1155_received`] in case of single token
    /// transfer, or [`IErc1155Receiver::on_erc1155_batch_received`] in
    /// case of batch transfer on the `to` address.
    ///
    /// The acceptance call is not executed and treated as a no-op if the
    /// target address doesn't contain code (i.e. an EOA). Otherwise,
    /// the recipient must implement either
    /// [`IErc1155Receiver::on_erc1155_received`] for single transfer, or
    /// [`IErc1155Receiver::on_erc1155_batch_received`] for a batch transfer,
    /// and return the acceptance value to accept the transfer.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `operator` - Generally the address that initiated the token transfer
    ///   (e.g. the caller).
    /// * `from` - Account of the sender.
    /// * `to` - Account of the recipient.

//! Optional `Enumerable` extension of the ERC-721 standard.
//!
//! This implements an optional extension of [`super::super::Erc721`] defined in
//! the EIP that adds enumerability of all the token ids in the contract as well
//! as all token ids owned by each account.
//!
//! CAUTION: [`super::super::Erc721`] extensions that implement custom
//! [`super::super::Erc721::balance_of`] logic, such as `Erc721Consecutive`,
//! interfere with enumerability and should not be used together with
//! [`Erc721Enumerable`].

use alloc::{vec, vec::Vec};

use alloy_primitives::{aliases::B32, uint, Address, U256};
use openzeppelin_stylus_proc::interface_id;
pub use sol::*;
use stylus_sdk::{
    prelude::*,
    storage::{StorageMap, StorageU256, StorageVec},
};

use crate::{
    token::erc721::{self, IErc721},
    utils::introspection::erc165::IErc165,
};

#[cfg_attr(coverage_nightly, coverage(off))]
mod sol {
    use alloy_sol_macro::sol;

    sol! {
        /// Indicates an error when an `owner`'s token query
        /// was out of bounds for `index`.
        ///
        /// NOTE: The owner being [`Address::ZERO`]
        /// indicates a global out of bounds index.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error ERC721OutOfBoundsIndex(address owner, uint256 index);

        /// Indicates an error related to batch minting not allowed.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error ERC721EnumerableForbiddenBatchMint();
    }
}

/// An [`Erc721Enumerable`] extension error.
#[derive(SolidityError, Debug)]
pub enum Error {
    /// Indicates an error when an `owner`'s token query
    /// was out of bounds for `index`.
    ///
    /// NOTE: The owner being [`Address::ZERO`]
    /// indicates a global out of bounds index.
    OutOfBoundsIndex(ERC721OutOfBoundsIndex),

    /// Indicates an error related to batch minting not allowed.
    EnumerableForbiddenBatchMint(ERC721EnumerableForbiddenBatchMint),
}

impl MethodError for Error {
    fn encode(self) -> alloc::vec::Vec<u8> {
        self.into()
    }
}

/// State of an [`Erc721Enumerable`] contract.
#[storage]
pub struct Erc721Enumerable {
    /// Maps owners to a mapping of indices to token IDs. The maximum index
    /// stores the owner's token count.
    pub(crate) owned_tokens: StorageMap<Address, StorageMap<U256, StorageU256>>,
    /// Maps tokens ids to indices in `owned_tokens`.
    pub(crate) owned_tokens_index: StorageMap<U256, StorageU256>,
    /// Stores all tokens ids.
    pub(crate) all_tokens: StorageVec<StorageU256>,
    /// Maps indices at `all_tokens` to tokens ids.
    pub(crate) all_tokens_index: StorageMap<U256, StorageU256>,
}

/// This is the interface of the optional `Enumerable` extension
/// of the ERC-721 standard.
#[interface_id]
pub trait IErc721Enumerable {
    /// The error type associated to this ERC-721 enumerable trait
    /// implementation.
    type Error: Into<alloc::vec::Vec<u8>>;

    /// Returns a token ID owned by `owner` at a given `index` of its token
    /// list.
    ///
    /// Use along with [`super::super::Erc721::balance_of`] to enumerate all of
    /// `owner`'s tokens.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `owner` - Address of token's owner.
    /// * `index` - Index of the token at `owner`'s tokens list.
    ///
    /// # Errors
    ///
    /// * [`Error::OutOfBoundsIndex`] - If an `owner`'s token query is out of
    ///   bounds for `index`.
    fn token_of_owner_by_index(
        &self,
        owner: Address,
        index: U256,
    ) -> Result<U256, Self::Error>;

    /// Returns the total amount of tokens stored by the contract.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    fn total_supply(&self) -> U256;

    /// Returns a token ID at a given `index` of all the tokens
    /// stored by the contract.
    ///
    /// Use along with [`Self::total_supply`] to
    /// enumerate all tokens.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the contract's state.
    /// * `index` - Index of the token in all tokens list.
    ///
    /// # Errors
    ///
    /// * [`Error::OutOfBoundsIndex`] - If an `owner`'s token query is out of
    ///   bounds for `index`.
    fn token_by_index(&self, index: U256) -> Result<U256, Self::Error>;
}

#[public]
#[implements(IErc721Enumerable<Error = Error>, IErc165)]
impl Erc721Enumerable {}

#[public]
impl IErc721Enumerable for Erc721Enumerable {
    type Error = Error;

    fn token_of_owner_by_index(
        &self,
        owner: Address,
        index: U256,
    ) -> Result<U256, Error> {
        let owned_tokens = self.owned_tokens.getter(owner);
        let token = owned_tokens.get(index);
        let owner_token_count = owned_tokens.get(U256::MAX);

        if owner_token_count.is_zero() {
            // v0.3.0 did not store an owner count. Preserve its behavior for
            // legacy nonzero token IDs while requiring an explicit count
            // backfill for owners whose only legacy token is ID zero.
            if token.is_zero() {
                Err(ERC721OutOfBoundsIndex { owner, index }.into())
            } else {
                Ok(token)
            }
        } else if index >= owner_token_count {
            Err(ERC721OutOfBoundsIndex { owner, index }.into())
        } else {
            Ok(token)
        }
    }

    fn total_supply(&self) -> U256 {
        let tokens_length = self.all_tokens.len();
        U256::from(tokens_length)
    }

    fn token_by_index(&self, index: U256) -> Result<U256, Error> {
        self.all_tokens.get(index).ok_or(
            ERC721OutOfBoundsIndex { owner: Address::ZERO, index }.into(),
        )
    }
}

#[public]
impl IErc165 for Erc721Enumerable {
    fn supports_interface(&self, interface_id: B32) -> bool {
        <Self as IErc721Enumerable>::interface_id() == interface_id
            || <Self as IErc165>::interface_id() == interface_id
    }
}

impl Erc721Enumerable {
    /// Initializes the stored owner count for an owner with v0.3.0 state.
    ///
    /// Call this during an application migration for each existing owner
    /// before relying on owner-index enumeration for a legacy token ID zero.
    /// Other legacy nonzero token IDs remain readable without this call.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to this extension's state.
    /// * `owner` - Address whose legacy token count is being initialized.
    /// * `erc721` - Read access to the paired ERC-721 implementation.
    ///
    /// # Errors
    ///
    /// * [`erc721::Error::InvalidOwner`] - If `owner` is
    ///   [`Address::ZERO`].
    pub fn _initialize_owner_enumeration(
        &mut self,
        owner: Address,
        erc721: &impl IErc721<Error = erc721::Error>,
    ) -> Result<(), erc721::Error> {
        let owner_token_count = erc721.balance_of(owner)?;
        self.owned_tokens
            .setter(owner)
            .setter(U256::MAX)
            .set(owner_token_count);

        Ok(())
    }

    /// Function to add a token to this extension's
    /// ownership-tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `to` - Address representing the new owner of the given `token_id`.
    /// * `token_id` - ID of the token to be added to the tokens list of the
    ///   given address.
    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
    ///
    /// # Errors
    ///
    /// * [`erc721::Error::InvalidOwner`] - If owner address is
    ///   [`Address::ZERO`].
    pub fn _add_token_to_owner_enumeration(
        &mut self,
        to: Address,
        token_id: U256,
        erc721: &impl IErc721<Error = erc721::Error>,
    ) -> Result<(), erc721::Error> {
        let balance = erc721.balance_of(to)?;
        let length = balance - uint!(1_U256);
        self.owned_tokens.setter(to).setter(length).set(token_id);
        self.owned_tokens_index.setter(token_id).set(length);
        self.owned_tokens.setter(to).setter(U256::MAX).set(balance);

        Ok(())
    }

    /// Function to add a token to this extension's token
    /// tracking data structures.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` - ID of the token to be added to the tokens list.
    pub fn _add_token_to_all_tokens_enumeration(&mut self, token_id: U256) {
        let index = self.total_supply();

        self.all_tokens_index.setter(token_id).set(index);
        self.all_tokens.push(token_id);
    }

    /// Function to remove a token from this extension's
    /// ownership-tracking data structures.
    ///
    /// Note that while the token is not assigned a new owner,
    /// the `self.owned_tokens_index` mapping is NOT updated:
    /// this allows for  gas optimizations e.g.
    /// when performing a transfer operation (avoiding double writes).
    ///
    /// This has O(1) time complexity, but alters the order
    /// of the `self.owned_tokens` array.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Address representing the previous owner of the given
    ///   `token_id`.
    /// * `token_id` - ID of the token to be removed from the tokens list of the
    ///   given address.
    /// * `erc721` - Read access to a contract providing [`IErc721`] interface.
    ///
    /// # Errors
    ///
    /// * [`erc721::Error::InvalidOwner`] - If owner address is
    ///   [`Address::ZERO`].
    pub fn _remove_token_from_owner_enumeration(
        &mut self,
        from: Address,
        token_id: U256,
        erc721: &impl IErc721<Error = erc721::Error>,
    ) -> Result<(), erc721::Error> {
        // To prevent a gap in from's tokens array,
        // we store the last token in the index of the token to delete,
        // and then delete the last slot (swap and pop).
        let last_token_index = erc721.balance_of(from)?;
        let token_index = self.owned_tokens_index.get(token_id);

        let mut owned_tokens_by_owner = self.owned_tokens.setter(from);

        // When the token to delete is the last token,
        // the swap operation is unnecessary.
        if token_index != last_token_index {
            let last_token_id = owned_tokens_by_owner.get(last_token_index);

            // Move the last token to the slot of the to-delete token.
            owned_tokens_by_owner.setter(token_index).set(last_token_id);
            // Update the moved token's index.
            self.owned_tokens_index.setter(last_token_id).set(token_index);
        }

        // This also deletes the contents at the last position of the array.
        self.owned_tokens_index.delete(token_id);
        owned_tokens_by_owner.delete(last_token_index);
        owned_tokens_by_owner.setter(U256::MAX).set(last_token_index);

        Ok(())
    }

    /// Function to remove a token from this extension's
    /// token tracking data structures.
    ///
    /// This has O(1) time complexity,
    /// but alters the order of the `self.all_tokens` array.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `token_id` -  ID of the token to be removed from the tokens list.
    ///
    /// # Panics
    ///
    /// * The function should not panic in a regular way.
    pub fn _remove_token_from_all_tokens_enumeration(
        &mut self,
        token_id: U256,
    ) {
        // To prevent a gap in the tokens array,
        // we store the last token in the index of the token to delete,
        // and then delete the last slot (swap and pop).
        let last_token_index = U256::from(self.all_tokens.len() - 1);
        let token_index = self.all_tokens_index.get(token_id);

        // When the token to delete is the last token,
        // the swap operation is unnecessary.
        // However, since this occurs so
        // rarely (when the last minted token is burnt)
        // that we still do the swap here
        // to avoid the gas cost of adding an 'if' statement
        // (like in `self._remove_token_from_owner_enumeration`).
        let last_token_id = self
            .all_tokens
            .get(last_token_index)
            .expect("token at given index must exist");

        // Move the last token to the slot of the to-delete token.
        self.all_tokens
            .setter(token_index)
            .expect("slot at given `token_index` must exist")
            .set(last_token_id);

        // Update the moved token's index.
        self.all_tokens_index.setter(last_token_id).set(token_index);

        // This also deletes the contents at the last position of the array.
        self.all_tokens_index.delete(token_id);
        self.all_tokens.pop();
    }

    /// See [`erc721::Erc721::_increase_balance`].
    /// Check if tokens can be minted in batch.
    ///
    /// Mechanism to be consistent with [Solidity version](https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v5.0.0/contracts/token/ERC721/extensions/ERC721Enumerable.sol#L163-L171)
    ///
    /// # Arguments
    ///
    /// * `amount` - The number of tokens to increase balance.
    ///
    /// # Errors
    ///
    /// * [`Error::EnumerableForbiddenBatchMint`] - If an `amount` is greater
    ///   than `0`.
    pub fn _check_increase_balance(amount: u128) -> Result<(), Error> {
        if amount > 0 {
            Err(ERC721EnumerableForbiddenBatchMint {}.into())
        } else {
            Ok(())
        }
    }
}

