    ///
    /// * If updated balance exceeds [`U256::MAX`].
    pub fn _mint_batch(
        &mut self,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._do_mint(to, ids, values, data)
    }

