//! Optional Metadata of the ERC-721 standard.

use alloc::{
    string::{String, ToString},
    vec,
    vec::Vec,
};

use alloy_primitives::U256;
use openzeppelin_stylus_proc::interface_id;
use stylus_sdk::{prelude::*, storage::StorageString};

