        &self,
        signature: &Signature,
        message: &[u8],
    ) -> ProjectivePoint {
        let R = signature.R;
        let A = self.point;

        let mut h = Sha512::new();
        h.update(CompressedPointY::from(R.into_affine()));
        h.update(CompressedPointY::from(A.into_affine()));
        h.update(message);

