169	    pub(crate) signing_key: ExpandedSecretKey,
170	    /// The public half of this signing key.
205	    ///  let secret_key: SecretKey = [1u8; SECRET_KEY_LENGTH];
206	    ///  let signing_key = SigningKey::from_bytes(&secret_key);
207	    ///  let message = b"Sign me!";
208	    ///
209	    ///  let signature = signing_key.sign(message);
210	    ///  assert!(signing_key.is_valid_signature(message, &signature));
211	    /// ```
212	    #[must_use]
213	    pub fn sign(&self, message: &[u8]) -> Signature {
214	        let mut h = Sha512::new();
215	
216	        h.update(self.signing_key.hash_prefix);
217	        h.update(message);
218	
219	        let mut r_hash = h.finalize();
220	        let mut r_integer = U512::from_bytes_le(r_hash.as_slice());
221	        let mut r_wide = WideScalar::from_bigint(r_integer);
222	        r_integer.zeroize();
223	        r_hash.as_mut_slice().zeroize();
224	        let mut r = Scalar::from_fp(r_wide);
225	        r_wide.zeroize();
226	
227	        let R = ProjectivePoint::generator() * r;
228	
229	        h = Sha512::new();
230	        h.update(CompressedPointY::from(R.into_affine()));
231	        h.update(CompressedPointY::from(
232	            self.verifying_key.point.into_affine(),
233	        ));
234	        h.update(message);
235	
236	        let mut k_hash = h.finalize();
237	        let mut k_integer = U512::from_bytes_le(k_hash.as_slice());
238	        let k_wide = WideScalar::from_bigint(k_integer);
239	        k_integer.zeroize();
240	        k_hash.as_mut_slice().zeroize();
241	        let k = Scalar::from_fp(k_wide);
242	        let mut secret_product = k * self.signing_key.scalar;
243	        let s: Scalar = secret_product + r;
244	        secret_product.zeroize();
245	        r.zeroize();
