392	    /// Helper for verification. Computes the expected `R` component of the
393	    /// signature. The caller compares this to the real `R` component.
394	    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
395	    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
396	    fn compute_R(
397	        &self,
398	        signature: &Signature,
399	        message: &[u8],
400	    ) -> ProjectivePoint {
401	        let R = signature.R;
402	        let A = self.point;
403	
404	        let mut h = Sha512::new();
405	        h.update(CompressedPointY::from(R.into_affine()));
406	        h.update(CompressedPointY::from(A.into_affine()));
407	        h.update(message);
408	
409	        let k = WideScalar::from_bigint(U512::from_bytes_le(
410	            h.finalize().as_slice(),
411	        ));
412	        let k = Scalar::from_fp(k);
413	
414	        // Compute R: `-[k]A + [s]B = R`.
415	        A * (-k) + ProjectivePoint::generator() * signature.s
416	    }
