219	        let mut z_s = v.iter().map(|g| g.z).collect::<Vec<_>>();
220	
221	        batch_inversion(&mut z_s);
222	
223	        // Perform affine transformations.
224	        v.iter()
225	            .zip(z_s)
226	            .map(|(g, z)| {
227	                if g.is_zero() {
228	                    Affine::zero()
229	                } else {
230	                    let x = g.x * z;
231	                    let y = g.y * z;
232	                    Affine::new_unchecked(x, y)
233	                }
234	            })
