 881	                    .unwrap_or_default();
 882	            }
 883	
 884	            let index2 = index + index2_shift;
 885	            if index2 < N {
 886	                // Possible to copy the second part of limb with bit AND
 887	                // operation, since the previous limbs were left zero.
