    11	    parse_macro_input, FnArg, ItemTrait, LitStr, Result, Token, TraitItem,
    12	};
    13	
    14	/// Computes an interface id as an associated function for the trait.
    15	pub(crate) fn interface_id(
    16	    _attr: &TokenStream,
    17	    input: TokenStream,
    18	) -> TokenStream {
    19	    let mut input = parse_macro_input!(input as ItemTrait);
    20	
    21	    let unsafety = input.unsafety;
    22	    let mut selectors_map = HashMap::<String, String>::new();
    23	    let mut selectors = Vec::<(
    24	        String,
    25	        proc_macro2::TokenStream,
    26	        proc_macro2::TokenStream,
    27	    )>::new();
    28	
    29	    for item in &mut input.items {
    30	        let TraitItem::Fn(func) = item else {
    31	            continue;
    32	        };
    33	
    34	        let mut override_fn_name = None;
    35	        for attr in mem::take(&mut func.attrs) {
    36	            if attr.path().is_ident("selector") {
    37	                if override_fn_name.is_some() {
    38	                    error!(attr.path(), "more than one selector attribute");
    39	                }
    40	                let args: SelectorArgs = match attr.parse_args() {
    41	                    Ok(args) => args,
    42	                    Err(error) => error!(attr.path(), "{}", error),
    43	                };
    44	                override_fn_name = Some(args.name);
    45	            } else {
    46	                // Put back any other attributes.
    47	                func.attrs.push(attr);
    48	            }
    49	        }
    50	
    51	        let rust_fn_name = func.sig.ident.to_string();
    52	
    53	        let solidity_fn_name =
    54	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
    55	
    56	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
    57	            FnArg::Typed(t) => Some(t.ty.clone()),
    58	            // Opt out any `self` arguments.
    59	            FnArg::Receiver(_) => None,
    60	        });
    61	
    62	        // Build the function signature string for selector computation.
    63	        let type_strings: Vec<String> =
    64	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
    65	        let signature =
    66	            format!("{}({})", solidity_fn_name, type_strings.join(","));
    67	
    68	        let selector_bytes = quote! {
    69	            stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*)
    70	        };
    71	        let selector = quote! {
    72	            alloy_primitives::aliases::B32::new(#selector_bytes)
    73	        };
    74	        let selector_value = quote! { u32::from_be_bytes(#selector_bytes) };
    75	
    76	        // Store selector expression from every function in the trait.
    77	        match selectors_map.get(&signature) {
    78	            Some(existing_rust_fn_name) => {
    79	                error!(
    80	                    existing_rust_fn_name,
    81	                    "duplicate Solidity signature: function '{}' has the same signature as function '{}': {}",
    82	                    rust_fn_name,
    83	                    existing_rust_fn_name,
    84	                    signature,
    85	                );
    86	            }
    87	            None => {
    88	                selectors_map.insert(signature, rust_fn_name.clone());
    89	                selectors.push((rust_fn_name, selector, selector_value));
    90	            }
    91	        };
    92	    }
    93	
    94	    let name = input.ident;
    95	    let vis = input.vis;
    96	    let attrs = input.attrs;
    97	    let trait_items = input.items;
    98	    let generics = input.generics.clone();
    99	    let where_clause = &generics.where_clause;
   100	
   101	    let supertrait_tokens = if input.supertraits.is_empty() {
   102	        quote! {}
   103	    } else {
   104	        let supertraits = &input.supertraits;
   105	        quote! { : #supertraits }
   106	    };
   107	
   108	    let selector_checks = selectors.iter().enumerate().flat_map(
   109	        |(left_index, (left_name, _, left_selector))| {
   110	            selectors.iter().skip(left_index + 1).map(
   111	                move |(right_name, _, right_selector)| {
   112	                    let message = format!(
   113	                        "selector collision detected between functions '{}' and '{}'",
   114	                        left_name, right_name
   115	                    );
   116	                    quote! {
   117	                        assert!(#left_selector != #right_selector, #message);
   118	                    }
   119	                },
   120	            )
   121	        },
   122	    );
   123	    let interface_id_selectors =
   124	        selectors.iter().map(|(_, selector, _)| selector);
   125	
   126	    // Keep the same trait with an additional associated function
   127	    // `interface_id`.
   128	    quote! {
   129	        const _: () = {
   130	            #(#selector_checks)*
   131	        };
   132	
   133	        #(#attrs)*
   134	        #vis #unsafety trait #name #generics #supertrait_tokens #where_clause {
   135	            #(#trait_items)*
   136	
   137	            #[cfg(not(feature = "contract-client-gen"))]
   138	            #[allow(missing_docs)]
   139	            fn __stylus_trait_and_impl_must_be_tagged_with_public_macro(&self);
   140	
   141	            #[doc = concat!("Solidity interface id associated with ", stringify!(#name), " trait.")]
   142	            #[doc = "Computed as a XOR of selectors for each function in the trait."]
   143	            fn interface_id() -> alloy_primitives::aliases::B32
   144	            where
   145	                Self: Sized,
   146	            {
   147	                #(#interface_id_selectors)^*
   148	            }
   149	        }
   150	    }
   151	    .into()
   152	}
