   154	/// Contains arguments of the `#[selector(..)]` attribute.
   155	struct SelectorArgs {
   156	    name: String,
   157	}
   158	
   159	impl Parse for SelectorArgs {
   160	    fn parse(input: ParseStream) -> Result<Self> {
   161	        let ident: Ident = input.parse()?;
   162	
   163	        if ident == "name" {
   164	            let _: Token![=] = input.parse()?;
   165	            let lit: LitStr = input.parse()?;
   166	            Ok(SelectorArgs { name: lit.value() })
   167	        } else {
   168	            error!(@ident, "expected identifier 'name'")
   169	        }
   170	    }
   171	}
