134	#[interface_id]
135	pub trait IErc2981: IErc165 {
136	    /// Returns how much royalty is owed and to whom, based on a sale price that
137	    /// may be denominated in any unit of exchange.
138	    ///
139	    /// The royalty amount is denominated and should be paid in that same unit
140	    /// of exchange.
141	    ///
142	    /// NOTE: ERC-2981 allows setting the royalty to 100% of the price.
143	    /// In that case all the price would be sent to the royalty receiver and 0
144	    /// tokens to the seller. Contracts dealing with royalty should consider
145	    /// empty transfers.
146	    ///
147	    /// # Arguments
