168	    fn royalty_info(
169	        &self,
170	        token_id: U256,
171	        sale_price: U256,
172	    ) -> (Address, U256) {
173	        let royalty_info = self.token_royalty_info.get(token_id);
174	        let (royalty_receiver, royalty_fraction) =
175	            if royalty_info.receiver.get().is_zero() {
176	                (
177	                    &self.default_royalty_info.receiver,
178	                    &self.default_royalty_info.royalty_fraction,
179	                )
180	            } else {
181	                (&royalty_info.receiver, &royalty_info.royalty_fraction)
182	            };
183	
184	        let royalty_amount = sale_price.mul_div(
185	            U256::from(royalty_fraction.get()),
186	            U256::from(self._fee_denominator()),
187	            Rounding::Floor,
188	        );
189	
190	        (royalty_receiver.get(), royalty_amount)
191	    }
192	}
