352	impl UUPSUpgradeable {
353	    /// Initializes implementation-only state used for context checks.
354	    ///
355	    /// Sets `logic_flag = true` in the implementation’s storage to indicate
356	    /// a direct (non-delegated) execution context.
357	    ///
358	    /// # Arguments
359	    ///
360	    /// * `&mut self` - Write access to the contract's state.
361	    #[constructor]
362	    pub fn constructor(&mut self) {
363	        self.logic_flag().set(true);
364	    }
365	
366	    /// Sets the proxy-stored runtime `version` for this logic
367	    /// (initializer-like).
368	    ///
369	    /// Intended to be called via a proxy ([`delegate_call`][delegate_call]) to
370	    /// record `VERSION_NUMBER` in the proxy’s storage.
371	    /// A consumer that exposes a public wrapper must restrict it to the
372	    /// contract's upgrade authority. Initializers can call this method
373	    /// internally after initializing the authority state.
374	    ///
375	    /// # Arguments
376	    ///
377	    /// * `&mut self` - Write access to the contract's state.
378	    ///
379	    /// # Errors
380	    ///
381	    /// * [`Error::UnauthorizedCallContext`] - If not called via proxy
382	    ///   `[`delegate_call`][delegate_call]`.
383	    /// * [`Error::InvalidVersion`] - If the proxy's stored `version` is greater
384	    ///   than this logic's `VERSION_NUMBER`.
385	    ///
386	    /// [delegate_call]: stylus_sdk::call::delegate_call
387	    pub fn set_version(&mut self) -> Result<(), Error> {
388	        if self.not_delegated().is_ok() {
389	            return Err(Error::UnauthorizedCallContext(
390	                UUPSUnauthorizedCallContext {},
391	            ));
392	        }
393	        if self.version.get() > VERSION_NUMBER {
394	            return Err(Error::InvalidVersion(InvalidVersion {
395	                current_version: self.version.get().to(),
396	            }));
397	        }
398	
399	        self.version.set(VERSION_NUMBER);
400	        Ok(())
401	    }
402	}
