462	    /// Ensures the call is being made through a valid [ERC-1967] proxy.
463	    ///
464	    /// Checks:
465	    /// 1. Execution is happening via [`delegate_call`][delegate_call] (checked
466	    ///    via `!self.is_logic()`).
467	    /// 2. The caller is a valid [ERC-1967] proxy (implementation slot is
468	    ///    non-zero).
469	    /// 3. The proxy state is consistent for this logic (the proxy-stored
470	    ///    version equals this logic's `VERSION_NUMBER`).
471	    ///
472	    /// [`onlyProxy`]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/c64a1edb67b6e3f4a15cca8909c9482ad33a02b0/contracts/proxy/utils/UUPSUpgradeable.sol#L50
473	    ///
474	    /// # Security Implications
475	    ///
476	    /// This check prevents direct calls to upgrade functions on the
477	    /// implementation contract.
478	    ///
479	    /// Note: This is not a reentrancy guard. Use a dedicated mechanism if
480	    /// reentrancy protection is required.
481	    ///
482	    /// # Edge Cases
483	    ///
484	    /// * Calls from [ERC-1167] minimal proxies are not guaranteed to pass this
485	    ///   check
486	    ///
487	    /// # Arguments
488	    ///
489	    /// * `&self` - Read access to the contract's state.
490	    ///
491	    /// # Errors
492	    ///
493	    /// * [`Error::UnauthorizedCallContext`] - If any of the above conditions is
494	    ///   not met
495	    ///
496	    /// [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
497	    /// [ERC-1167]: https://eips.ethereum.org/EIPS/eip-1167
498	    /// [delegate_call]: stylus_sdk::call::delegate_call
499	    pub fn only_proxy(&self) -> Result<(), Error> {
500	        if self.is_logic()
501	            || Erc1967Utils::get_implementation(self) == Address::ZERO
502	            || U32::from(self.get_version()) != self.version.get()
503	        {
504	            Err(Error::UnauthorizedCallContext(UUPSUnauthorizedCallContext {}))
505	        } else {
506	            Ok(())
507	        }
508	    }
