510	    /// Check that the execution is not being performed through a
511	    /// [`delegate_call`].
512	    ///
513	    /// This allows a function to be callable on the implementing contract
514	    /// but not through proxies.
515	    ///
516	    /// # Arguments
517	    ///
518	    /// * `&self` - Read access to the contract's state.
519	    ///
520	    /// # Errors
521	    ///
522	    /// * [`Error::UnauthorizedCallContext`] - If the execution is performed via
523	    ///   [`delegate_call`].
524	    ///
525	    /// [`delegate_call`]: stylus_sdk::call::delegate_call
526	    pub fn not_delegated(&self) -> Result<(), Error> {
527	        if self.is_logic() {
528	            Ok(())
529	        } else {
530	            Err(Error::UnauthorizedCallContext(UUPSUnauthorizedCallContext {}))
531	        }
532	    }
