   144	    /// * `new_implementation` - The address of the new implementation.
   145	    ///
   146	    /// # Errors
   147	    ///
   148	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
   149	    ///   contract.
   150	    /// * [`Error::UnauthorizedAccount`] - If the caller is not the owner.
   151	    ///
   152	    /// # Events
   153	    ///
   154	    /// * [`Upgraded`].
   155	    pub fn upgrade_to(
   156	        &mut self,
   157	        new_implementation: Address,
   158	    ) -> Result<(), Error> {
   159	        self.ownable.only_owner()?;
   160	        self.set_implementation(new_implementation)
