   163	    /// Upgrades the beacon to a new implementation.
   164	    ///
   165	    /// # Arguments
   166	    ///
   167	    /// * `&mut self` - Write access to the contract's state.
   168	    /// * `new_implementation` - The address of the new implementation.
   169	    ///
   170	    /// # Errors
   171	    ///
   172	    /// * [`Error::InvalidImplementation`] - If `new_implementation` is not a
   173	    ///   contract.
   174	    ///
   175	    /// # Events
   176	    ///
   177	    /// * [`Upgraded`].
   178	    fn set_implementation(
   179	        &mut self,
   180	        new_implementation: Address,
   181	    ) -> Result<(), Error> {
   182	        if self.vm().code_size(new_implementation) == 0 {
   183	            return Err(Error::InvalidImplementation(
   184	                BeaconInvalidImplementation {
   185	                    implementation: new_implementation,
   186	                },
   187	            ));
   188	        }
   189	        self.implementation.set(new_implementation);
   190	        self.vm().log(Upgraded { implementation: new_implementation });
   191	        Ok(())
   192	    }
