   255	/// Generate pairwise compile-time selector collision checks for a set of functions.
   256	///
   257	/// Each check is emitted as a separate `const _: () = { ... }` item so the compiler
   258	/// reports all collisions independently rather than stopping at the first.
   259	///
   260	/// Uses `const` assertions because selector values are computed by the `function_selector!`
   261	/// declarative macro after proc-macro expansion — the proc macro has no access to concrete
   262	/// selector bytes at the time it runs. The `function_selector!` macro expands to a
   263	/// const-evaluable keccak computation, making the `const` assertion viable.
   264	///
   265	/// Generates n*(n-1)/2 const assertion items (one per pair), where n is the number
   266	/// of regular (`FnKind::Function`) entries in the input — fallback, receive, and
   267	/// constructor route separately and are excluded.
   268	///
   269	/// **Not checked:** collisions across separate `#[public]`-annotated items (proc macros
   270	/// cannot share state across invocations), and collisions with methods inherited via
   271	/// `#[implements]` (only trait type paths are available — the inherited trait's function
   272	/// signatures are not accessible during proc-macro expansion).
   273	/// See the `#[public]` macro documentation in `lib.rs` for user-facing details.
   274	pub(super) fn selector_collision_checks<E: FnExtension>(funcs: &[PublicFn<E>]) -> Vec<syn::Item> {
   275	    let functions = regular_functions(funcs);
   276	
   277	    // Collect per-function data used in the pairwise comparison below.
   278	    let func_data: Vec<_> = functions
   279	        .iter()
   280	        .map(|f| {
   281	            (
   282	                f.selector_const(),
   283	                f.selector_name(),
   284	                f.display_label(),
   285	                f.name.span(),
   286	            )
   287	        })
   288	        .collect();
   289	    let n = func_data.len();
   290	    let mut checks: Vec<syn::Item> = Vec::with_capacity(n * n.saturating_sub(1) / 2);
   291	    for (i, (const_a, sel_a, label_a, _)) in func_data.iter().enumerate() {
   292	        for (const_b, sel_b, label_b, span) in &func_data[i + 1..] {
   293	            let msg = format!(
   294	                "Stylus SDK: ABI selector collision: {label_a} and {label_b} produce the same \
   295	                 4-byte selector. Use #[selector(name = \"...\")] to assign a distinct name, \
   296	                 or rename one",
   297	            );
   298	            // The cfg gate is intentional: `contract-client-gen` generates call stubs for
   299	            // external contracts whose ABI the user does not control. Blocking compilation
   300	            // over a selector collision in a foreign interface would be unhelpful — the
   301	            // collision only matters for routing, which is not emitted in contract-client-gen mode.
   302	            checks.push(parse_quote_spanned! { *span =>
   303	                #[cfg(not(feature = "contract-client-gen"))]
   304	                const _: () = {
   305	                    use stylus_sdk::function_selector;
   306	                    #const_a
   307	                    #const_b
   308	                    assert!(#sel_a != #sel_b, #msg);
   309	                };
   310	            });
   311	        }
   312	    }
   313	    checks
   314	}
