418	    /// Transfers a `value` amount of tokens of type `ids` from `from` to
419	    /// `to`. Will mint (or burn) if `from` (or `to`) is the [`Address::ZERO`].
420	    ///
421	    /// NOTE: The ERC-1155 acceptance check is not performed in this function.
422	    /// See [`Self::_update_with_acceptance_check`] instead.
423	    ///
424	    /// # Arguments
425	    ///
426	    /// * `&mut self` - Write access to the contract's state.
427	    /// * `from` - Account to transfer tokens from.
428	    /// * `to` - Account of the recipient.
429	    /// * `ids` - Array of all tokens ids.
430	    /// * `values` - Array of all amount of tokens to be transferred.
431	    ///
432	    /// # Errors
433	    ///
434	    /// * [`Error::InvalidArrayLength`] - If length of `ids` is not equal to
435	    ///   length of `values`.
436	    /// * [`Error::InsufficientBalance`] - If `value` is greater than the
437	    ///   balance of the `from` account.
438	    ///
439	    ///
440	    /// # Events
441	    ///
442	    /// * [`TransferSingle`] - If the arrays contain one element.
443	    /// * [`TransferBatch`] - If the arrays contain multiple elements.
444	    ///
445	    /// # Panics
446	    ///
447	    /// * If updated balance exceeds [`U256::MAX`], may happen during `mint`
448	    ///   operation.
449	    fn _update(
450	        &mut self,
451	        from: Address,
452	        to: Address,
453	        ids: Vec<U256>,
454	        values: Vec<U256>,
455	    ) -> Result<(), Error> {
456	        Self::require_equal_arrays_length(&ids, &values)?;
457	
458	        // Preflight source balances so a later insufficient item cannot leave
459	        // earlier batch items applied when a caller catches the returned Err.
460	        // A self-transfer subtracts and adds each item immediately, so each
461	        // item is checked against the unchanged balance independently.
462	        if !from.is_zero() && from != to {
463	            let mut remaining_balances: Vec<(U256, U256)> = Vec::new();
464	            for (&token_id, &value) in ids.iter().zip(values.iter()) {
465	                let index = remaining_balances
466	                    .iter()
467	                    .position(|(id, _)| *id == token_id);
468	                let balance = match index {
469	                    Some(index) => remaining_balances[index].1,
470	                    None => self.balance_of(from, token_id),
471	                };
472	
473	                if balance < value {
474	                    return Err(Error::InsufficientBalance(
475	                        ERC1155InsufficientBalance {
476	                            sender: from,
477	                            balance,
478	                            needed: value,
479	                            token_id,
480	                        },
481	                    ));
482	                }
483	
484	                let remaining = balance - value;
485	                if let Some(index) = index {
486	                    remaining_balances[index].1 = remaining;
487	                } else {
488	                    remaining_balances.push((token_id, remaining));
489	                }
490	            }
491	        }
492	
493	        let operator = self.vm().msg_sender();
494	
495	        for (&token_id, &value) in ids.iter().zip(values.iter()) {
496	            self.do_update(from, to, token_id, value)?;
497	        }
498	
499	        if ids.len() == 1 {
500	            let id = ids[0];
501	            let value = values[0];
502	            self.vm().log(TransferSingle { operator, from, to, id, value });
503	        } else {
504	            self.vm().log(TransferBatch { operator, from, to, ids, values });
505	        }
506	
507	        Ok(())
508	    }
