   145	    fn token_of_owner_by_index(
   146	        &self,
   147	        owner: Address,
   148	        index: U256,
   149	    ) -> Result<U256, Error> {
   150	        let owned_tokens = self.owned_tokens.getter(owner);
   151	        let token = owned_tokens.get(index);
   152	        let owner_token_count = owned_tokens.get(U256::MAX);
   153	
   154	        if owner_token_count.is_zero() {
   155	            // v0.3.0 did not store an owner count. Preserve its behavior for
   156	            // legacy nonzero token IDs while requiring an explicit count
   157	            // backfill for owners whose only legacy token is ID zero.
   158	            if token.is_zero() {
   159	                Err(ERC721OutOfBoundsIndex { owner, index }.into())
   160	            } else {
   161	                Ok(token)
   162	            }
   163	        } else if index >= owner_token_count {
   164	            Err(ERC721OutOfBoundsIndex { owner, index }.into())
   165	        } else {
   166	            Ok(token)
   167	        }
   168	    }
