 73	    carry: Limb,
 74	) -> (Limb, Limb) {
 75	    let a = a as WideLimb;
 76	    let carry = carry as WideLimb;
 77	    let tmp = a + widening_mul(b, c) + carry;
 78	    let carry = (tmp >> Limb::BITS) as Limb;
 79	    (tmp as Limb, carry)
