 85	pub const fn adc(a: Limb, b: Limb, carry: bool) -> (Limb, bool) {
 86	    let a = a as WideLimb;
 87	    let b = b as WideLimb;
 88	    let carry = carry as WideLimb;
 89	    let tmp = a + b + carry;
 90	    let carry = (tmp >> Limb::BITS) != 0;
 91	    (tmp as Limb, carry)
