 60	    /// Create a new Poseidon sponge.
 61	    #[must_use]
 62	    #[inline]
 63	    pub fn new() -> Self {
 64	        Self {
 65	            phantom: core::marker::PhantomData,
 66	            state: vec![F::zero(); P::T].into_boxed_slice(),
 67	            mode: Mode::Absorbing,
 68	            // Begin index from `CAPACITY`. Skip capacity elements.
 69	            index: P::CAPACITY,
 70	        }
 71	    }
