  94	impl ExpandedSecretKey {
  95	    /// Construct secret key [`Self`] from a byte string of any length.
  96	    ///
  97	    /// Secret key will be derived from hashed `bytes`.
  98	    pub(crate) fn from_bytes(bytes: &[u8]) -> ExpandedSecretKey {
  99	        let mut scalar_bytes = [0u8; 32];
 100	        let mut hash_prefix = [0u8; 32];
 101	        scalar_bytes.copy_from_slice(&bytes[00..32]);
 102	        hash_prefix.copy_from_slice(&bytes[32..64]);
 103	
 104	        // Clamp in place so the pre-clamped copy is not left in a temporary.
 105	        scalar_bytes[0] &= 0b1111_1000;
 106	        scalar_bytes[31] &= 0b0111_1111;
 107	        scalar_bytes[31] |= 0b0100_0000;
 108	        let mut scalar_integer = U256::from_bytes_le(&scalar_bytes);
 109	        let mut scalar = Scalar::from_bigint(scalar_integer);
 110	        scalar_integer.zeroize();
 111	        scalar_bytes.zeroize();
 112	        let expanded = Self { scalar, hash_prefix };
 113	        scalar.zeroize();
 114	        hash_prefix.zeroize();
 115	        expanded
 116	    }
