1027	    pub fn _deposit(
1028	        &mut self,
1029	        caller: Address,
1030	        receiver: Address,
1031	        assets: U256,
1032	        shares: U256,
1033	        erc20: &mut Erc20,
1034	    ) -> Result<(), Error> {
1035	        // If asset() is ERC-777, `transfer_from` can trigger a reentrancy
1036	        // BEFORE the transfer happens through the `tokens_to_send` hook. On the
1037	        // other hand, the `token_received` hook, that is triggered after the
1038	        // transfer, calls the vault, which is assumed not malicious.
1039	        //
