1064	    ///
1065	    /// # Arguments
1066	    ///
1067	    /// * `caller` - Address initiating the withdrawal.
1068	    /// * `receiver` - Address receiving the assets.
1069	    /// * `owner` - Address owning the shares.
1070	    /// * `assets` - Amount of underlying tokens to transfer.
1071	    /// * `shares` - Amount of shares to burn.
1072	    /// * `erc20` - Write access to an [`Erc20`] contract.
1073	    ///
1074	    /// # Errors
1075	    ///
1076	    /// * [`erc20::Error::InsufficientAllowance`] - If `caller` needs allowance.
1077	    /// * [`erc20::Error::InvalidApprover`] - If `owner` is [`Address::ZERO`].
1078	    /// * [`erc20::Error::InsufficientBalance`] - If `owner` lacks shares.
1079	    /// * [`safe_erc20::Error::SafeErc20FailedOperation`] - If transfer fails.
1080	    ///
1081	    /// # Events
1082	    ///
1083	    /// * [`Withdraw`]
1084	    pub fn _withdraw(
1085	        &mut self,
1086	        caller: Address,
1087	        receiver: Address,
1088	        owner: Address,
1089	        assets: U256,
1090	        shares: U256,
1091	        erc20: &mut Erc20,
1092	    ) -> Result<(), Error> {
1093	        let remaining_allowance = if caller != owner {
1094	            Some(erc20._allowance_after_spending(owner, caller, shares)?)
1095	        } else {
1096	            None
1097	        };
1098	
1099	        // If asset() is ERC-777, `transfer` can trigger a reentrancy AFTER the
1100	        // transfer happens through the `tokens_received` hook. On the other
1101	        // hand, the `tokens_to_send` hook, that is triggered before the
1102	        // transfer, calls the vault, which is assumed not malicious.
1103	        //
1104	        // Conclusion: we need to do the transfer after the burn so that any
1105	        // reentrancy would happen after the shares are burned and after the
1106	        // assets are transferred, which is a valid state.
1107	
1108	        erc20._burn(owner, shares)?;
1109	        if let Some(remaining_allowance) = remaining_allowance {
1110	            erc20._write_spent_allowance(owner, caller, remaining_allowance)?;
1111	        }
1112	
1113	        // If this external transfer fails, callers must propagate the error
1114	        // for the EVM to revert the prior share burn and allowance update.
1115	        self.safe_erc20.safe_transfer(self.asset(), receiver, assets)?;
1116	
1117	        self.vm().log(Withdraw {
1118	            sender: caller,
1119	            receiver,
1120	            owner,
1121	            assets,
1122	            shares,
1123	        });
1124	
1125	        Ok(())
1126	    }
