 317	    /// Mint wrapped token to cover any underlying tokens that would have been
 318	    /// transferred by mistake or acquired from rebasing mechanisms.
 319	    ///
 320	    /// Internal function that can be exposed with access control if desired.
 321	    ///
 322	    /// # Arguments
 323	    ///
 324	    /// * `&mut self` - Write access to the contract's state.
 325	    /// * `account` - The account to mint tokens to.
 326	    /// * `erc20` - Write access to an [`Erc20`] contract.
 327	    ///
 328	    /// # Errors
 329	    ///
 330	    /// * [`Error::InvalidUnderlying`]  - If the external call for
 331	    ///   [`IErc20::balance_of`] fails.
 332	    /// * [`Error::InvalidReceiver`] - If the `account` address is
 333	    ///   [`Address::ZERO`].
 334	    ///
 335	    /// # Panics
 336	    ///
 337	    /// * If the underlying balance is less than the [`IErc20::total_supply`].
 338	    pub fn _recover(
 339	        &mut self,
 340	        account: Address,
 341	        erc20: &mut Erc20,
 342	    ) -> Result<U256, Error> {
 343	        let contract_address = self.vm().contract_address();
 344	
 345	        let underlying_token = Erc20Interface::new(self.underlying());
 346	
 347	        let underlying_balance = underlying_token
 348	            .balance_of(self.vm(), Call::new(), contract_address)
 349	            .map_err(|_| ERC20InvalidUnderlying { token: contract_address })?;
 350	
 351	        let value = underlying_balance
 352	            .checked_sub(erc20.total_supply())
 353	            .expect("underlying balance should be greater than the `IErc20::total_supply`");
 354	
 355	        if value > U256::ZERO {
 356	            erc20._mint(account, value)?;
 357	        }
 358	
 359	        Ok(value)
 360	    }
 361	}
